@layer components {
  :where([data-control-family="card"][data-slot="root"]) {
    --cui-card-radius: var(--radius-panel);
    --cui-card-background: var(--card);
    --cui-card-foreground: var(--card-foreground);
    --cui-card-hover-background: var(--hover-fill);
    --cui-card-border-color: var(--border);
    --cui-card-section-border-color: oklch(from var(--border) l c h / 0.7);
    --cui-card-border-width: var(--control-rim-width);
    --cui-card-shadow: var(--shadow-sm);
    --cui-card-backdrop-filter: none;
    --cui-card-padding-block: calc(var(--spacing) * 6);
    --cui-card-padding-inline: calc(var(--spacing) * 6);
    --cui-card-gap: calc(var(--spacing) * 6);
    --cui-card-title-font-size: 1em;
    --_card-corner: min(var(--cui-card-radius), var(--cui-card-padding-inline) + var(--cui-card-border-width));
    border: var(--cui-card-border-width) solid var(--cui-card-border-color);
    border-radius: var(--_card-corner);
    background: var(--cui-card-background);
    color: var(--cui-card-foreground);
    box-shadow: var(--cui-card-shadow);
    -webkit-backdrop-filter: var(--cui-card-backdrop-filter);
    backdrop-filter: var(--cui-card-backdrop-filter);
    gap: var(--cui-card-gap);
    padding-block: var(--cui-card-padding-block);
  }

  :where([data-control-family="card"][data-slot="header"]) {
    gap: calc(var(--spacing) * 1.5);
    padding-inline: var(--cui-card-padding-inline);
  }

  :where([data-control-family="card"][data-slot="content"]) {
    padding-inline: var(--cui-card-padding-inline);
  }

  :where([data-control-family="card"][data-slot="footer"]) {
    padding-inline: var(--cui-card-padding-inline);
  }

  :where([data-control-family="card"][data-slot="root"]:has([data-control-family="card"][data-slot="link"])) {
    position: relative;
  }

  @media (hover: hover) {
    :where(
        [data-control-family="card"][data-slot="root"]:has(
          [data-control-family="card"][data-slot="link"]:hover:not(:disabled, [aria-disabled="true"])
        )
      ) {
      background-image: linear-gradient(var(--cui-card-hover-background), var(--cui-card-hover-background));
    }
  }

  :where([data-control-family="card"][data-slot="root"]:has([data-control-family="card"][data-slot="link"]:focus-visible)) {
    outline: var(--focus-ring-width) var(--focus-ring-style) var(--focus-ring);
    outline-offset: var(--focus-ring-offset);
  }

  :where([data-control-family="card"][data-slot="link"]) {
    text-align: start;
    cursor: pointer;
    outline: none;
  }

  :where([data-control-family="card"][data-slot="link"]:is(:disabled, [aria-disabled="true"])) {
    cursor: not-allowed;
    opacity: var(--disabled-opacity);
  }

  :where([data-control-family="card"][data-slot="link"])::after {
    content: "";
    position: absolute;
    inset: 0;
    border-radius: var(--_card-corner);
  }

  :where([data-control-family="card"][data-slot="root"]:has([data-control-family="card"][data-slot="link"])) {
    --_card-link-lift-position: relative;
    --_card-link-lift-layer: 1;
  }

  @layer stretched-link {
    :where(
        [data-control-family="card"][data-slot="root"]
          :is(a[href], button, summary, input, select, textarea, [role="button"], [role="checkbox"], [role="radio"], [role="switch"]):not(
            [data-control-family="card"][data-slot="link"]
          )
      ) {
      position: var(--_card-link-lift-position, static);
      z-index: var(--_card-link-lift-layer, auto);
    }
  }

  :where([data-control-family="card"][data-slot="root"][data-size="sm"]) {
    --cui-card-padding-block: calc(var(--spacing) * 3);
    --cui-card-padding-inline: calc(var(--spacing) * 4);
    --cui-card-gap: calc(var(--spacing) * 3);
  }

  :where([data-control-family="card"][data-slot="root"][data-variant="sectioned"]) {
    --cui-card-shadow: var(--shadow-pop);
    gap: 0;
    padding-block: 0;
  }

  :where([data-control-family="card"][data-slot="root"][data-variant="sectioned"] > [data-slot="content"]) {
    padding-block: var(--cui-card-padding-block);
  }

  :where([data-control-family="card"][data-slot="root"][data-variant="sectioned"] > [data-slot="header"]) {
    padding-block: calc(var(--cui-card-padding-block) - var(--spacing));
    border-block-end: var(--control-rim-width) solid var(--cui-card-section-border-color);
  }

  :where([data-control-family="card"][data-slot="root"][data-variant="sectioned"] > [data-slot="footer"]) {
    padding-block: calc(var(--cui-card-padding-block) - var(--spacing));
    border-block-start: var(--control-rim-width) solid var(--cui-card-section-border-color);
  }

  :where([data-control-family="card"][data-slot="title"]) {
    font-size: var(--cui-card-title-font-size);
    font-weight: var(--font-weight-semibold);
    line-height: var(--leading-tight);
    text-wrap: balance;
  }

  :where([data-control-family="card"][data-slot="description"]) {
    color: var(--muted-foreground);
    font-size: var(--text-body);
    text-wrap: pretty;
  }
}

@property --cui-card-radius {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-card-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-card-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-card-section-border-color {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-card-hover-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-card-border-color {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-card-border-width {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-card-shadow {
  syntax: "*";
  inherits: true;
}

@property --cui-card-backdrop-filter {
  syntax: "*";
  inherits: true;
}

@property --cui-card-padding-block {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-card-padding-inline {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-card-gap {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

